mapper.select:
SELECT * FROM ( SELECT 'SALE' AS type, so.order_no AS orderNo, so.sale_time AS time, so.goods_amount AS goodsAmount, so.discount_amount AS discountAmount, so.payable_amount AS amount, so.cashier_name AS cashierName FROM sales_order so WHERE so.member_id = #{memberId}
AND so.sale_time >= #{begin}
AND so.sale_time <= CONCAT(#{end}, ' 23:59:59')
UNION ALL SELECT 'RETURN' AS type, rt.order_no AS orderNo, rt.return_time AS time, 0 AS goodsAmount, 0 AS discountAmount, rt.refund_amount AS amount, rt.cashier_name AS cashierName FROM return_order rt WHERE rt.member_id = #{memberId}
AND rt.return_time >= #{begin}
AND rt.return_time <= CONCAT(#{end}, ' 23:59:59')
) t ORDER BY t.time DESC, t.orderNo DESC
